package com.medflow.auth.controller;
import com.medflow.auth.dto.*; import com.medflow.auth.service.AuthService; import jakarta.validation.Valid; import java.security.Principal; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register") ResponseEntity<UserResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(auth.register(r));}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}@PostMapping("/staff") ResponseEntity<UserResponse> staff(@Valid @RequestBody StaffCreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(auth.createStaff(r));}@GetMapping("/me") UserResponse me(Principal p){return auth.me(p.getName());}}
